// Risk badge styling classes
const RISK_CLASS = {
  "Very Low-risk": "risk-verylow",
  "Low-risk": "risk-low",
  "Medium-risk": "risk-medium",
  "High-risk": "risk-high",
};
function riskClass(risk) {
  return RISK_CLASS[risk] || "risk-none";
}

// Sentiment badge styling classes
const SENTIMENT_CLASS = {
  "Very confident": "sentiment-pos",
  "Confident": "sentiment-pos",
  "Concerned": "sentiment-neg",
  "Very concerned": "sentiment-neg",
  "Dispare": "sentiment-neg",
};
function sentimentClass(sentiment) {
  return SENTIMENT_CLASS[sentiment] || "sentiment-none";
}

// Weighting badge styling classes
const WEIGHTING_CLASS = {
  "Overweight": "weight-over",
  "Neutral": "weight-neutral",
  "Underweight": "weight-under",
  "Exclusion": "weight-exclusion",
};
function weightingClass(weighting) {
  return WEIGHTING_CLASS[weighting] || "weight-none";
}

function formatPct(n) {
  const v = parseFloat(n);
  if (isNaN(v)) return null;
  const pct = v * 100;
  return (pct >= 0 ? "+" : "") + pct.toFixed(1) + "%";
}

// For return figures, which are already plain percentage numbers by the time
// they reach the UI (converted once in parseCSV / carried as-is from sample data)
function retDisplay(v) {
  const n = parseFloat(v);
  if (isNaN(n)) return "—";
  return (n >= 0 ? "+" : "") + n.toFixed(1) + "%";
}
// Formats an ISO date string like "2026-08-12" as "12 Aug 2026"
function formatDate(iso) {
  const d = new Date(iso);
  if (isNaN(d.getTime())) return "";
  const months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
  return d.getDate() + " " + months[d.getMonth()] + " " + d.getFullYear();
}

function retClass(v) {
  const n = parseFloat(v);
  return isNaN(n) || n >= 0 ? "up" : "down";
}

