  const sectors = useMemo(
    () => Array.from(new Set(stocks.map((s) => s.sector).filter(Boolean))).sort(),
    [stocks]
  );

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    let list = stocks;
    if (q) {
      list = list.filter(
        (s) => s.ticker.toLowerCase().includes(q) || s.name.toLowerCase().includes(q) || s.sector.toLowerCase().includes(q)
      );
    }
    if (sector !== "all") list = list.filter((s) => s.sector === sector);
    if (risk !== "all") list = list.filter((s) => s.risk === risk);
    if (weighting !== "all") list = list.filter((s) => s.weighting === weighting);
    if (sentiment !== "all") list = list.filter((s) => s.sentiment === sentiment);
    return applyLensAndRank(lens, list, rankBy);
  }, [stocks, query, sector, risk, weighting, sentiment, lens, rankBy]);

